class Provider {
    constructor() {
        this.api = "https://hentai2read.com";
        this.cdn = "https://hentaicdn.com/hentai";
        this.cache = {};
    }

    getSettings() {
        return {
            supportsMultiLanguage: false,
            supportsMultiScanlator: false,
        };
    }

    async search(opts) {
        var query = String((opts && opts.query) || "").trim();

        if (!query) {
            return await this.getLatest();
        }

        if (query.indexOf("hentai2read.com") >= 0) {
            var direct = await this.resultFromMangaUrl(query);
            return direct ? [direct] : [];
        }

        var slug = this.slugify(query);
        var directUrl = this.api + "/" + slug + "/";

        var directResult = await this.resultFromMangaUrl(directUrl);

        if (directResult && this.titleLooksRelevant(query, directResult.title)) {
            return [directResult];
        }

        var urls = [
            this.api + "/hentai-search?search=" + encodeURIComponent(query),
            this.api + "/hentai-search/?search=" + encodeURIComponent(query),
            this.api + "/hentai-search?q=" + encodeURIComponent(query),
            this.api + "/hentai-search/?q=" + encodeURIComponent(query),
            this.api + "/search?query=" + encodeURIComponent(query),
            this.api + "/search/?query=" + encodeURIComponent(query),
            this.api + "/hentai-list/all/any/all/last-added"
        ];

        var out = [];
        var seen = {};

        for (var i = 0; i < urls.length; i++) {
            try {
                var html = await this.fetchText(urls[i]);

                if (!html || html.length < 300) {
                    continue;
                }

                var results = this.parseSearchResults(html);

                for (var j = 0; j < results.length; j++) {
                    var item = results[j];

                    if (!item || !item.id || seen[item.id]) {
                        continue;
                    }

                    if (!this.titleLooksRelevant(query, item.title) && urls[i].indexOf("hentai-list") >= 0) {
                        continue;
                    }

                    seen[item.id] = true;
                    out.push(item);
                }

                if (out.length > 0) {
                    return out;
                }
            } catch (err) {
                console.error("hentai2read search failed: " + String(err));
            }
        }

        return [];
    }

    async findChapters(mangaId) {
        var url = this.normalizeMangaUrl(mangaId);

        if (!url) {
            return [];
        }

        try {
            var html = await this.fetchText(url);

            if (!html || html.length < 300) {
                return [];
            }

            var chapters = this.parseChapters(html, url);
            chapters = this.dedupeChapters(chapters);

            chapters.sort(function (a, b) {
                return Number(a.chapter || 0) - Number(b.chapter || 0);
            });

            for (var i = 0; i < chapters.length; i++) {
                chapters[i].index = i;

                if (!chapters[i].title) {
                    chapters[i].title = "Chapter " + chapters[i].chapter;
                }

                chapters[i].language = "en";
            }

            return chapters;
        } catch (err) {
            console.error("hentai2read findChapters failed: " + String(err));
            return [];
        }
    }

    async findChapterPages(chapterId) {
        var url = this.normalizeUrl(chapterId);

        if (!url) {
            return [];
        }

        try {
            var html = await this.fetchText(url);

            if (!html || html.length < 300) {
                return [];
            }

            var images = this.parseChapterImages(html);

            var pages = [];

            for (var i = 0; i < images.length; i++) {
                pages.push({
                    url: images[i],
                    index: i,
                    headers: {
                        Referer: url,
                        "User-Agent": "Mozilla/5.0",
                    },
                });
            }

            return pages;
        } catch (err) {
            console.error("hentai2read findChapterPages failed: " + String(err));
            return [];
        }
    }

    async getLatest() {
        var urls = [
            this.api + "/hentai-list/all/any/all/last-added",
            this.api + "/"
        ];

        for (var i = 0; i < urls.length; i++) {
            try {
                var html = await this.fetchText(urls[i]);
                var results = this.parseSearchResults(html);

                if (results.length > 0) {
                    return results;
                }
            } catch (err) {
                console.error("hentai2read latest failed: " + String(err));
            }
        }

        return [];
    }

    async resultFromMangaUrl(url) {
        url = this.normalizeMangaUrl(url);

        if (!url) {
            return null;
        }

        try {
            var html = await this.fetchText(url);

            if (!html || html.length < 300) {
                return null;
            }

            if (this.isBlockedText(html)) {
                return null;
            }

            var title =
                this.cleanText(this.firstMatch(html, /<h1[^>]*>([\s\S]*?)<\/h1>/i)) ||
                this.cleanText(this.firstMatch(html, /<h2[^>]*>([\s\S]*?)<\/h2>/i)) ||
                this.cleanText(this.firstMatch(html, /<title[^>]*>([\s\S]*?)<\/title>/i)) ||
                this.titleFromUrl(url);

            title = title
                .replace(/\s*-\s*Read.*$/i, "")
                .replace(/\s*Hentai.*$/i, "")
                .trim();

            var image =
                this.firstMatch(html, /<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i) ||
                this.firstMatch(html, /<img[^>]+class=["'][^"']*(?:cover|thumb|poster)[^"']*["'][^>]+src=["']([^"']+)["']/i) ||
                this.firstMatch(html, /<img[^>]+src=["']([^"']+)["'][^>]+alt=["'][^"']*`?/i) ||
                "";

            return {
                id: url,
                title: this.decode(title || this.titleFromUrl(url)),
                synonyms: [],
                year: this.extractYear(html),
                image: this.normalizeUrl(image),
            };
        } catch (err) {
            return null;
        }
    }

    parseSearchResults(html) {
        var results = [];
        var seen = {};
        var self = this;

        try {
            var $ = LoadDoc(html);

            $("a.mangaPopover[href], a[href]").each(function (i, e) {
                var href = e.attr("href") || "";
                var fullUrl = self.normalizeMangaUrl(href);

                if (!fullUrl || seen[fullUrl]) {
                    return;
                }

                if (!self.isMangaUrl(fullUrl)) {
                    return;
                }

                var title =
                    e.attr("data-title") ||
                    e.attr("title") ||
                    e.find("img").attr("alt") ||
                    e.find(".title").first().text() ||
                    e.find(".text-ellipsis").first().text() ||
                    e.text() ||
                    "";

                title = self.cleanSearchTitle(title);

                if (!title) {
                    title = self.titleFromUrl(fullUrl);
                }

                if (self.isBlockedText(title)) {
                    return;
                }

                var image =
                    e.find("img").attr("data-src") ||
                    e.find("img").attr("data-original") ||
                    e.find("img").attr("src") ||
                    "";

                seen[fullUrl] = true;

                results.push({
                    id: fullUrl,
                    title: title,
                    synonyms: [],
                    year: 1,
                    image: self.normalizeUrl(image),
                });
            });
        } catch (err) {
            console.error("hentai2read LoadDoc search parse failed: " + String(err));
        }

        var pattern = /<a[^>]+href=["']([^"']+)["'][^>]*?(?:data-title=["']([^"']+)["'])?[^>]*>([\s\S]*?)<\/a>/gi;
        var match;

        while ((match = pattern.exec(html)) !== null) {
            var href = this.decode(match[1] || "");
            var fullUrl = this.normalizeMangaUrl(href);

            if (!fullUrl || seen[fullUrl] || !this.isMangaUrl(fullUrl)) {
                continue;
            }

            var inner = match[3] || "";
            var title =
                this.cleanSearchTitle(match[2] || "") ||
                this.cleanSearchTitle(this.firstMatch(inner, /data-title=["']([^"']+)["']/i)) ||
                this.cleanSearchTitle(this.firstMatch(inner, /title=["']([^"']+)["']/i)) ||
                this.cleanSearchTitle(this.firstMatch(inner, /alt=["']([^"']+)["']/i)) ||
                this.cleanSearchTitle(inner) ||
                this.titleFromUrl(fullUrl);

            if (this.isBlockedText(title)) {
                continue;
            }

            var image =
                this.firstMatch(inner, /data-src=["']([^"']+)["']/i) ||
                this.firstMatch(inner, /data-original=["']([^"']+)["']/i) ||
                this.firstMatch(inner, /src=["']([^"']+)["']/i) ||
                "";

            seen[fullUrl] = true;

            results.push({
                id: fullUrl,
                title: title,
                synonyms: [],
                year: 1,
                image: this.normalizeUrl(this.decode(image)),
            });
        }

        return results;
    }

    parseChapters(html, mangaUrl) {
        var chapters = [];
        var seen = {};
        var self = this;

        try {
            var $ = LoadDoc(html);

            $("[data-cid]").each(function (i, e) {
                var chapterId = e.attr("data-cid") || "";
                var href = e.attr("href") || "";

                if (!href) {
                    href = e.find("a[href]").first().attr("href") || "";
                }

                var fullUrl = self.normalizeUrl(href);

                if (!fullUrl || !self.isChapterUrl(fullUrl) || seen[fullUrl]) {
                    return;
                }

                var chapterNo = self.chapterNumberFromUrl(fullUrl);
                var title =
                    e.attr("title") ||
                    e.text() ||
                    "Chapter " + chapterNo;

                title = self.cleanChapterTitle(title, chapterNo);

                seen[fullUrl] = true;

                chapters.push({
                    id: fullUrl,
                    url: fullUrl,
                    title: title,
                    chapter: String(chapterNo),
                    index: 0,
                    language: "en",
                });
            });

            $("a[href]").each(function (i, e) {
                var href = e.attr("href") || "";
                var fullUrl = self.normalizeUrl(href);

                if (!fullUrl || !self.isChapterUrl(fullUrl) || seen[fullUrl]) {
                    return;
                }

                if (self.sameMangaBase(mangaUrl, fullUrl) === false) {
                    return;
                }

                var chapterNo = self.chapterNumberFromUrl(fullUrl);

                if (!chapterNo) {
                    return;
                }

                var title =
                    e.attr("title") ||
                    e.text() ||
                    "Chapter " + chapterNo;

                title = self.cleanChapterTitle(title, chapterNo);

                seen[fullUrl] = true;

                chapters.push({
                    id: fullUrl,
                    url: fullUrl,
                    title: title,
                    chapter: String(chapterNo),
                    index: 0,
                    language: "en",
                });
            });
        } catch (err) {
            console.error("hentai2read LoadDoc chapters parse failed: " + String(err));
        }

        var patterns = [
            /<a[^>]+data-cid=["']?([0-9]+)["']?[^>]+href=["']([^"']+\/[0-9]+(?:\.[0-9]+)?\/?)["'][^>]*>([\s\S]*?)<\/a>/gi,
            /<a[^>]+href=["']([^"']+\/[0-9]+(?:\.[0-9]+)?\/?)["'][^>]+data-cid=["']?([0-9]+)["']?[^>]*>([\s\S]*?)<\/a>/gi,
            /<a[^>]+href=["']([^"']+\/[0-9]+(?:\.[0-9]+)?\/?)["'][^>]*>([\s\S]*?)<\/a>/gi
        ];

        for (var p = 0; p < patterns.length; p++) {
            var match;

            while ((match = patterns[p].exec(html)) !== null) {
                var href;
                var inner;

                if (p === 0) {
                    href = match[2] || "";
                    inner = match[3] || "";
                } else {
                    href = match[1] || "";
                    inner = match[3] || match[2] || "";
                }

                var fullUrl = this.normalizeUrl(this.decode(href));

                if (!fullUrl || !this.isChapterUrl(fullUrl) || seen[fullUrl]) {
                    continue;
                }

                if (this.sameMangaBase(mangaUrl, fullUrl) === false) {
                    continue;
                }

                var chapterNo = this.chapterNumberFromUrl(fullUrl);

                if (!chapterNo) {
                    continue;
                }

                var title =
                    this.cleanChapterTitle(this.firstMatch(inner, /title=["']([^"']+)["']/i), chapterNo) ||
                    this.cleanChapterTitle(this.firstMatch(inner, /alt=["']([^"']+)["']/i), chapterNo) ||
                    this.cleanChapterTitle(inner, chapterNo);

                seen[fullUrl] = true;

                chapters.push({
                    id: fullUrl,
                    url: fullUrl,
                    title: title || ("Chapter " + chapterNo),
                    chapter: String(chapterNo),
                    index: 0,
                    language: "en",
                });
            }
        }

        return chapters;
    }

    parseChapterImages(html) {
        var images = [];
        var seen = {};
        var self = this;

        function add(raw) {
            var url = self.decode(String(raw || "").trim());

            if (!url) {
                return;
            }

            url = url
                .replace(/\\u0026/g, "&")
                .replace(/\\\//g, "/")
                .replace(/&amp;/g, "&");

            if (url.indexOf("//") === 0) {
                url = "https:" + url;
            } else if (url.indexOf("http") !== 0) {
                if (url.indexOf("/") !== 0) {
                    url = "/" + url;
                }

                if (url.indexOf("/hentai/") === 0) {
                    url = "https://hentaicdn.com" + url;
                } else {
                    url = self.cdn + url;
                }
            }

            if (seen[url]) {
                return;
            }

            seen[url] = true;
            images.push(url);
        }

        var imageJson = this.firstMatch(html, /['"]images['"]\s*:\s*(\[[\s\S]*?\])\s*,/i) ||
                        this.firstMatch(html, /['"]images['"]\s*:\s*(\[[\s\S]*?\])/i);

        if (imageJson) {
            try {
                var arr = JSON.parse(imageJson);

                if (Array.isArray(arr)) {
                    for (var i = 0; i < arr.length; i++) {
                        add(arr[i]);
                    }
                }
            } catch (err) {
                var strPattern = /["']([^"']+\.(?:jpg|jpeg|png|webp|gif)(?:\?[^"']*)?)["']/gi;
                var sm;

                while ((sm = strPattern.exec(imageJson)) !== null) {
                    add(sm[1]);
                }
            }
        }

        try {
            var $ = LoadDoc(html);

            $("img").each(function (i, e) {
                add(e.attr("data-src") || "");
                add(e.attr("data-original") || "");
                add(e.attr("src") || "");
            });
        } catch (err) {
        }

        var patterns = [
            /https?:\/\/hentaicdn\.com\/hentai\/[^"'<>\s\\]+/gi,
            /\/\/hentaicdn\.com\/hentai\/[^"'<>\s\\]+/gi,
            /\/hentai\/[^"'<>\s\\]+\.(?:jpg|jpeg|png|webp|gif)(?:\?[^"'<>\s\\]+)?/gi
        ];

        for (var p = 0; p < patterns.length; p++) {
            var match;

            while ((match = patterns[p].exec(html)) !== null) {
                add(match[0]);
            }
        }

        return images;
    }

    normalizeMangaUrl(input) {
        var url = this.normalizeUrl(input);

        if (!url) {
            return "";
        }

        url = url.replace(/[?#].*$/g, "");

        if (this.isChapterUrl(url)) {
            url = url.replace(/\/[0-9]+(?:\.[0-9]+)?\/?$/g, "/");
        }

        if (!url.endsWith("/")) {
            url += "/";
        }

        return url;
    }

    normalizeUrl(input) {
        var url = this.decode(String(input || "").trim());

        if (!url) {
            return "";
        }

        url = url.replace(/&amp;/g, "&");

        if (url.indexOf("//") === 0) {
            return "https:" + url;
        }

        if (url.indexOf("/") === 0) {
            return this.api + url;
        }

        if (url.indexOf("http") === 0) {
            return url;
        }

        return this.api + "/" + url;
    }

    isMangaUrl(url) {
        var text = String(url || "");

        if (text.indexOf(this.api) !== 0) {
            return false;
        }

        if (text.indexOf("/hentai-list/") >= 0) return false;
        if (text.indexOf("/hentai-search") >= 0) return false;
        if (text.indexOf("/tag/") >= 0) return false;
        if (text.indexOf("/artist/") >= 0) return false;
        if (text.indexOf("/category/") >= 0) return false;
        if (text.indexOf("/login") >= 0) return false;
        if (text.indexOf("/forum") >= 0) return false;

        return /hentai2read\.com\/[^\/?#]+\/?$/i.test(text) ||
               /hentai2read\.com\/[^\/?#]+\/[0-9]+(?:\.[0-9]+)?\/?$/i.test(text);
    }

    isChapterUrl(url) {
        return /hentai2read\.com\/[^\/?#]+\/[0-9]+(?:\.[0-9]+)?\/?$/i.test(String(url || ""));
    }

    sameMangaBase(mangaUrl, chapterUrl) {
        var a = String(this.normalizeMangaUrl(mangaUrl) || "");
        var b = String(this.normalizeMangaUrl(chapterUrl) || "");

        if (!a || !b) {
            return true;
        }

        return a === b;
    }

    chapterNumberFromUrl(url) {
        var match = String(url || "").match(/\/([0-9]+(?:\.[0-9]+)?)\/?$/);

        if (!match || !match[1]) {
            return 0;
        }

        return match[1];
    }

    titleFromUrl(url) {
        var match = String(url || "").match(/hentai2read\.com\/([^\/?#]+)/i);
        var slug = match && match[1] ? match[1] : "";

        return this.toTitle(slug);
    }

    slugify(input) {
        return String(input || "")
            .toLowerCase()
            .replace(/&/g, " and ")
            .replace(/['’]/g, "")
            .replace(/[^a-z0-9]+/g, "_")
            .replace(/^_+|_+$/g, "");
    }

    toTitle(slug) {
        return this.decode(String(slug || ""))
            .replace(/_/g, " ")
            .replace(/\s+/g, " ")
            .replace(/\b\w/g, function (m) {
                return m.toUpperCase();
            })
            .trim();
    }

    titleLooksRelevant(query, title) {
        var q = this.cleanComparable(query);
        var t = this.cleanComparable(title);

        if (!q || !t) {
            return false;
        }

        if (t.indexOf(q) >= 0 || q.indexOf(t) >= 0) {
            return true;
        }

        var parts = q.split(" ");
        var hits = 0;

        for (var i = 0; i < parts.length; i++) {
            if (parts[i].length >= 3 && t.indexOf(parts[i]) >= 0) {
                hits++;
            }
        }

        return hits >= Math.max(1, Math.ceil(parts.length * 0.6));
    }

    cleanComparable(input) {
        return String(input || "")
            .toLowerCase()
            .replace(/\[[^\]]+\]/g, " ")
            .replace(/[^a-z0-9]+/g, " ")
            .replace(/\s+/g, " ")
            .trim();
    }

    cleanSearchTitle(input) {
        var text = this.cleanText(input);

        text = text
            .replace(/\s*\[[^\]]+\]\s*$/g, "")
            .replace(/\s+/g, " ")
            .trim();

        if (text.length > 180) {
            text = text.slice(0, 180).trim();
        }

        return text;
    }

    cleanChapterTitle(input, chapterNo) {
        var text = this.cleanText(input);

        text = text
            .replace(/\s+/g, " ")
            .replace(/^chapter\s*/i, "")
            .replace(/^ch\.\s*/i, "")
            .trim();

        if (!text) {
            return "Chapter " + chapterNo;
        }

        if (text.length > 180) {
            text = text.slice(0, 180).trim();
        }

        var lower = text.toLowerCase();

        if (
            lower.indexOf("bookmark") >= 0 ||
            lower.indexOf("report") >= 0 ||
            lower.indexOf("discussion") >= 0 ||
            lower.indexOf("login") >= 0 ||
            lower.indexOf("privacy") >= 0 ||
            lower.indexOf("terms") >= 0
        ) {
            return "Chapter " + chapterNo;
        }

        return text;
    }

    isBlockedText(input) {
        var t = String(input || "").toLowerCase();

        return (
            t.indexOf("lolicon") >= 0 ||
            t.indexOf("shotacon") >= 0 ||
            t.indexOf("shota") >= 0 ||
            t.indexOf("loli") >= 0 ||
            t.indexOf("underage") >= 0 ||
            t.indexOf("minor") >= 0
        );
    }

    extractYear(html) {
        var year =
            this.firstMatch(html, /Release Year\s*[-:]?\s*([0-9]{4})/i) ||
            this.firstMatch(html, /year["']?\s*[:=]\s*["']?([0-9]{4})/i);

        return Number(year || 1) || 1;
    }

    dedupeChapters(chapters) {
        var seen = {};
        var ret = [];

        for (var i = 0; i < chapters.length; i++) {
            var ch = chapters[i];
            var key = ch.id || ch.url || ch.chapter;

            if (!key || seen[key]) {
                continue;
            }

            seen[key] = true;
            ret.push(ch);
        }

        return ret;
    }

    async fetchText(url) {
        var cached = this.cache[url];

        if (cached && cached.expires > Date.now()) {
            return cached.text;
        }

        var res = await fetch(url, {
            headers: {
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                "Accept-Language": "en-US,en;q=0.9",
                "User-Agent": "Mozilla/5.0",
                "Referer": this.api + "/",
            },
        });

        if (!res.ok) {
            throw new Error("HTTP " + res.status + " for " + url);
        }

        var text = await res.text();

        this.cache[url] = {
            text: text,
            expires: Date.now() + 5 * 60 * 1000,
        };

        return text;
    }

    firstMatch(text, pattern) {
        var match = String(text || "").match(pattern);
        return match && match[1] ? match[1] : "";
    }

    cleanText(input) {
        return this.decode(
            String(input || "")
                .replace(/<script[\s\S]*?<\/script>/gi, " ")
                .replace(/<style[\s\S]*?<\/style>/gi, " ")
                .replace(/<[^>]+>/g, " ")
                .replace(/\s+/g, " ")
                .trim()
        );
    }

    decode(input) {
        return String(input || "")
            .replace(/&amp;/g, "&")
            .replace(/&quot;/g, "\"")
            .replace(/&#39;/g, "'")
            .replace(/&apos;/g, "'")
            .replace(/&lt;/g, "<")
            .replace(/&gt;/g, ">")
            .replace(/&#x2F;/g, "/")
            .replace(/&#47;/g, "/")
            .replace(/&nbsp;/g, " ");
    }
}
